// Native-only storage ABI. Actual addresses are written and consumed on the
// GPU; JavaScript sees only the browser's opaque resource objects. A logical
// renderer buffer can exceed the browser's per-shared-allocation size limit.
template<class T> struct OmwPaged {
    const unsigned long long* pages;
    T* direct;
    unsigned long long first;
    __device__ OmwPaged(const unsigned long long* table):pages(table),direct(nullptr),first(0) {}
    __device__ OmwPaged(T* pointer):pages(nullptr),direct(pointer),first(0) {}
    template<class U> __device__ OmwPaged(const OmwPaged<U>& other):pages(other.pages),direct(other.direct),first(other.first) {}
    __device__ T& operator[](unsigned long long index) const {
        index+=first;
        if(direct)return direct[index];
        unsigned long long bytes=index*sizeof(T);
        return *reinterpret_cast<T*>(pages[bytes>>26]+(bytes&67108863ull));
    }
    __device__ OmwPaged operator+(unsigned long long offset) const {
        OmwPaged result=*this;result.first+=offset;return result;
    }
};

// Authored WebCuda implementation of debug and outline shader arithmetic.
__global__ void shade_debug_vertices(const unsigned long long* omw_pages_vertices,const unsigned long long* omw_pages_attributes,const unsigned long long* omw_pages_matrix_ids,const unsigned long long* omw_pages_params,unsigned int vertex_count) {
OmwPaged<float> vertices(omw_pages_vertices);
OmwPaged<const float> attributes(omw_pages_attributes);
OmwPaged<const unsigned int> matrix_ids(omw_pages_matrix_ids);
OmwPaged<const float> params(omw_pages_params);

    unsigned int i=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    if(i>=vertex_count)return;
    unsigned int p=matrix_ids[i]*16u,v=i*10u,kind=(unsigned int)params[p];
    if(kind==0u)return;
    if(kind==2u||kind==3u) {
        for(unsigned int k=0;k<3;k++)vertices[v+k]=vertices[v+k]*params[p+12u+k]+params[p+8u+k];
        vertices[v+3u]=1.0f;
        float lighting=0.5f;
        for(unsigned int k=0;k<3;k++) {
            float normal=kind==3u?1.0f:attributes[i*34u+3u+k];
            float light=k==0u?1.0f:(k==1u?0.5f:2.0f);
            lighting+=normal*light*(0.5f/sqrtf(5.25f));
        }
        for(unsigned int k=0;k<3;k++)vertices[v+4u+k]=(kind==3u?attributes[i*34u+3u+k]:params[p+4u+k])*lighting;
        vertices[v+7u]=1.0f;
    } else if(kind==4u||params[p+1u]==0.0f) {
        for(unsigned int k=0;k<4;k++)vertices[v+4u+k]=params[p+4u+k];
    }
}
